/-- An array's grouped-unit counts agree row-by-row with the birthday benchmark. -/
def CountAlignment {groupSize : ℕ} (A : ScheduleArray groupSize) (M : ℕ) : Prop :=
  ∀ r, A.grouped r = birthdayGroupedUnits M (A.popSize r)

/-- The number of randomized groups tends to infinity. -/
def GroupCountGrowth {M : ℕ} (A : ScheduleArray M) : Prop :=
  Tendsto A.groups atTop atTop

/-- Ordered pairs of disjoint slice elements. -/
abbrev OrderedDisjointPair (n M : ℕ) :=
  {P : Omega n M × Omega n M // Disjoint P.1.1 P.2.1}

/-- Row control-group count. -/
def ScheduleArray.controls {M : ℕ} (A : ScheduleArray M) (r : ℕ) : ℕ :=
  A.groups r - A.treated r

/-- Row grouped-unit count. -/
def ScheduleArray.grouped {M : ℕ} (A : ScheduleArray M) (r : ℕ) : ℕ :=
  M * A.groups r

/-- Complete treatment assignments to the realized groups. -/
abbrev TreatmentSpace (G G1 : ℕ) :=
  {S : Finset (Fin G) // S.card = G1}

